import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"证券化与发起-分销","description":"","frontmatter":{"title":"证券化与发起-分销","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/securitization-otd.md","filePath":"econ/securitization-otd.md","lastUpdated":1789023840000}'),c={name:"econ/securitization-otd.md"};function A(h,a,u,B,_,D){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="证券化与发起-分销" tabindex="-1">证券化与发起-分销 <a class="header-anchor" href="#证券化与发起-分销" aria-label="Permalink to &quot;证券化与发起-分销&quot;">​</a></h1><div class="epigraph"><p>把贷款切成档、卖掉，可以把风险移出资产负债表，也把监测激励移出；发起–分销在信息不可验证时，用评级与结构替代关系。</p><footer>—— 据 Gorton and Metrick 对证券化与影子银行的综述；Keys, Mukherjee, Seru and Vig, Journal of Monetary Economics / QJE 相关工作；Tirole, Theory of Corporate Finance</footer></div><p><a href="/econ/credit-rating-agencies">上一课</a>指出结构化产品是评级购物的温床。本课缺口是发起–分销（OTD）：企业（与银行）为何证券化、风险转移是否真实、监测如何退化。不重写主体评级的通过周期，不把限价簿上的 MBS 做市写成主线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持有至到期要求资本与监督。证券化：资产池、破产隔离、分档，把优先档卖给要安全资产的客户（Miller 客户、货币基金），留存或卖掉劣后。Gorton–Metrick：这是影子银行生产安全债的技术。Keys 等：当贷款更容易被证券化、监测标准下降时，违约更差——OTD 的道德风险。缺口是对企业融资的含义：应收账款、租赁、项目现金流都可以出表；看起来 WACC 下降，可能只是把风险与监测卖给了不理解档次的买家。</p><p><span class="marginnote">真实出售 vs 隐性担保：发起人为声誉在危机中把资产买回，风险未转移。APV 若按出表减债、又不计或有回购，会高估股权价值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>动机清单：监管资本套利；分散地域/行业；获得比企业主体更优的档次定价（结构优于主体）；流动性。成本：开销、留存要求、柠檬（买家怕被选差资产）、监测下降。Tirole：可验证现金流（标准化按揭、合格应收）更适合分档；软信息贷款证券化则信息损失最大。</p><p>对企业资本结构：证券化像有抵押的优先债加出售期权。杠杆的经济口径应并表风险，而不是只看主体报表。动态权衡的 \\(D^\\ast\\) 若按表内债计算，会被 OTD 绕开——直到隐性担保实现。</p>',9)),(e(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E8%B5%84%E4%BA%A7%E6%B1%A0%22%5D%20--%3E%20TRAN%5B%22%E5%88%86%E6%A1%A3%22%5D%0A%20%20TRAN%20--%3E%20AAA%5B%22%E4%BC%98%E5%85%88%3A%20%E5%AE%89%E5%85%A8%E5%AE%A2%E6%88%B7%22%5D%0A%20%20TRAN%20--%3E%20EQ%5B%22%E5%8A%A3%E5%90%8E%3A%20%E7%95%99%E5%AD%98%E6%88%96%E5%8D%96%E6%8E%89%22%5D%0A%20%20OTD%5B%22%E5%8D%96%E5%87%BA%E7%9B%91%E6%B5%8B%E6%9D%83%22%5D%20--%3E%20MH%5B%22%E7%AD%9B%E9%80%89%E4%B8%8E%E7%9B%91%E7%9D%A3%E4%B8%8B%E9%99%8D%22%5D%0A%20%20REC%5B%22%E9%9A%90%E6%80%A7%E5%9B%9E%E8%B4%AD%22%5D%20--%3E%20BS%5B%22%E9%A3%8E%E9%99%A9%E5%9B%9E%E5%88%B0%E5%8F%91%E8%B5%B7%E4%BA%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与关系：OTD 是关系的反面——信息标准化、可转让。关系课的竞争与转卖在此完成。评级购物给优先档盖章，使不监测的买家愿意持有。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是要求权再切与激励再切。MM 说切片不改变资产；OTD 试图改变的是<strong>谁监测</strong>与<strong>哪套监管权重</strong>。若监测改变资产本身的违约（筛选松了），资产收益流变了，不是纯切片。这是 MM 假设失败的又一例：切片技术改变了现金流。</p><p>危机：优先档的安全是条件安全，依赖相关违约不高、评级不跳。宏观课序的影子挤兑是优先档的批发融资逃跑。企业若依赖资产支持商业票据为营运资本融资，展期课的墙出现在表外管道。</p><h3 id="不要把证券化写成「一定不好」" tabindex="-1">不要把证券化写成「一定不好」 <a class="header-anchor" href="#不要把证券化写成「一定不好」" aria-label="Permalink to &quot;不要把证券化写成「一定不好」&quot;">​</a></h3><p>风险真正转移、监测用留存与对价维持时，专业化可以有收益。问题是激励不相容的 OTD 加监管套利。资本预算对出表融资应做并表情景与回购情景两套 APV。</p><p><span class="marginnote">Keys, Mukherjee, Seru, Vig：易于证券化的贷款质量更差，是监测激励的证据。引用其期刊论文即可，不要编造编号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成 CDO 结构图全集。下一课财务困境：当 OTD 失败、资产回到表内或管道冻结，企业进入重组。第 11 章处理的是主体，管道有另一套破产隔离——隔离失败是隐性担保的法律表达。</p><p>后课默认：OTD 改变监测与监管口径；经济杠杆可以与表内杠杆分家。评级与安全档客户是需求侧。真实出售假设必须做压力。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>证券化分档服务安全债客户，也把监测从发起人挪走。</li><li>筛选下降与隐性担保使 MM 切片假设失败：资产本身变了。</li><li>出表不能自动降低经济资本成本；APV 要并表与回购情景。</li><li>出处：Gorton–Metrick；Keys, Mukherjee, Seru and Vig；Tirole。</li></ul>',12))])}const f=i(c,[["render",A]]);export{m as __pageData,f as default};
